// === Tab: mySketch ===
// Attractor_5.0

let N = 10000 ;
let K = 0.1 ; let H = 0.0005 ; let A = 0.5 ; let F = 1.5 ; let dT = 0.01 ;

let S[] = new Array(N)  ; let dS[] = new Array(N) ; let T ; let PX ; let PY ; let I ;



function setup(){

  createCanvas(600, 620) ; noSmooth() ; background(0) ; 

  PX = random(-3,+3) ; PY = random(-3,+3) ;
  for ( I = 0 ; I < N ; I++ ){
    S[I] = random(PX-0.01,PX+0.01) ; dS[I] = random(PY-0.01,PY+0.01) ;
  }

} // setup()



function draw(){

  background(0) ;

  stroke(255,0,0) ; 
  for ( I = N-1 ; I >= 0 ; I-- ){
    dS[I] = dS[I] + ( (sin(S[I])) - (K*S[I]) - (H*dS[I]) + (A*sin(2*PI*F*T)) ) ;
    S[I] = S[I] + (dS[I]/100) ;
    if ( I == 0 ){ stroke(255) ; fill(255) ; ellipse(S[I]*25+300,-dS[I]*4+200,6,6) ; }
             else{ point(S[I]*25+300,-dS[I]*4+200) ; }
  }
  T = T + dT ;

  strokeWeight(4) ; fill(255) ; stroke(0) ; ellipse(150,500,20,20) ; ellipse(520,500,20,20) ; PX = 250+(S[0]*10) ;
  stroke(180,180,0) ; arc(150,500,20,20,PI/2,3*PI/2) ; line(150,490,PX,490) ; 
  noFill() ; PY = 500+(A*sin(2*PI*F*T)/K) ; beginShape() ; vertex(PX,490) ;
  for ( I = 0 ; I < 200 ; I++ ){
    vertex( (PY-PX)*float(I)/200 + PX + (10*sin(float(I)/4)) , 490 + (6*cos(float(I)/4)) ) ;
  }
  vertex(PY,490) ; endShape() ; line(PY,490,520,490) ;
  PX = 250-(S[0]*10) ; line(150,510,PX,510) ; PY =500-(A*sin(2*PI*F*T)/K) ; beginShape() ; vertex(PX,510) ;
  for ( I = 0 ; I < 200 ; I++ ){
    vertex( (PY-PX)*float(I)/200 + PX + (10*sin(float(I)/4)) , 510 + (6*cos(float(I)/4)) ) ;
  }
  vertex(PY,510) ; endShape() ; line(PY,510,520,510) ; arc(520,500,20,20,-PI/2,+PI/2) ;
  noFill() ; stroke(255) ; line(520,500,520,550) ; rect(470,550,100,50) ; 
  fill(255) ; textSize(20) ; text("oscillator",475,580) ;
  ellipse(150+(100*sin(S[0])),500+(-100*cos(S[0])),40,40) ; 
  line(150,500,150+(100*sin(S[0])),500+(-100*cos(S[0]))) ; strokeWeight(1) ; textSize(14) ;
  line(100,200,500,200) ; line(500,200,490,190) ; line(500,200,490,210) ; text("displacement",505,205) ;
  line(300,20,300,380) ; line(300,20,290,30) ; line(300,20,310,30) ; text("velocity",275,15) ;

}// draw()



function mousePressed(){ setup() ; }

